/* ---------- interactive theory ---------- */
function onTheory(root){
  const w=root.querySelector('#w-compass');
  if(w){w.innerHTML=`<b>Компас вокруг магнита</b><label>Положение компаса: <output id="cmo"></output><input type="range" id="cm" min="0" max="355" step="5" value="30"></label>
    <div class="row" style="display:flex;gap:8px;flex-wrap:wrap;margin:4px 0"><button class="btn ghost" id="cmf">Перевернуть магнит</button></div><div id="cmp" class="fig"></div><div id="cmt" style="text-align:center"></div>`;
    let first='N';const g=id=>w.querySelector('#'+id);const base={};
    const u=()=>{const a=+g('cm').value*Math.PI/180;g('cmo').textContent=g('cm').value+'°';const x=160+125*Math.cos(a),y=100-78*Math.sin(a);
      if(!base[first])base[first]=magPic(first);const [bx,by]=Bf(magPoles(first),x,y);
      g('cmp').innerHTML=SV(320,200,base[first]+needle(x,y,bx,by,14),'Компас вокруг магнита');
      g('cmt').innerHTML=`Красный (северный) конец стрелки смотрит <span class="out">по линии поля</span>: от N, к S.`;};
    g('cm').oninput=u;g('cmf').onclick=()=>{first=other(first);u();};u();}
  const v=root.querySelector('#w-amp');
  if(v){v.innerHTML=`<b>Сила Ампера: поиграй с током и полюсами</b>
    <div class="row" style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0"><button class="btn" id="ai">Ток: к нам ⊙</button><button class="btn ghost" id="ap">Поменять полюса</button></div>
    <label>Сила тока I = <output id="aio"></output><input type="range" id="aI" min="0" max="5" step="0.5" value="2"></label><div id="apic" class="fig"></div><div id="atx" style="text-align:center"></div>`;
    let s=1,first='N';const g=id=>v.querySelector('#'+id);
    const u=()=>{const I=+g('aI').value;g('aio').textContent=N(I)+' А';const B=gapB('h',first);const F=cross([0,0,s],B);const k=vkey(F);const L=I*14;const [dx,dy]=k==='+y'?[0,-1]:[0,1];
      g('apic').innerHTML=SV(320,180,polesGap('h',first)+wire(160,90,I?s:0,14)+(I>0?ARR(160,90+dy*16,160,90+dy*(16+L),{c:'var(--bad)',sw:3,hs:11})+TX(176,90+dy*(16+L*0.6),'F',{c:'var(--bad)',a:'start'}):''),'Сила Ампера');
      g('ai').textContent=s>0?'Ток: к нам ⊙':'Ток: от нас ⊗';
      g('atx').innerHTML=I>0?`Поле: <span class="out">${DIR[vkey(B)]}</span> · ток: <span class="out">${s>0?'к нам':'от нас'}</span> → сила: <span class="out">${DIR[k]}</span><br><span class="small">Сила пропорциональна току: F = B·I·l</span>`:'Тока нет — силы нет.';};
    g('ai').onclick=()=>{s=-s;u();};g('ap').onclick=()=>{first=other(first);u();};g('aI').oninput=u;u();}
}

